INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6898653, 1039620, 12611, '<td valign="top">super capture. dripping with honest modern art photography ironic street cred.</td>', 'super capture. dripping with honest modern art photography ironic street cred.', '2012-11-05 10:41:46.000000', NULL, 1),
(6898816, 1039406, 96574, '<td valign="top">I wonder if this was shot in a small french town. My pick for the blue.</td>', 'I wonder if this was shot in a small french town. My pick for the blue.', '2012-11-05 12:41:50.000000', NULL, 1),
(6898817, 1039504, 96574, '<td valign="top">Love the placement of the sun and the runners to create those great long shadows.</td>', 'Love the placement of the sun and the runners to create those great long shadows.', '2012-11-05 12:42:32.000000', NULL, 1),
(6898821, 1039626, 96509, '<td valign="top">Nice lighting, well executed. I would prefer a better defined shadow and a bit more texture in the apple it seems a bit flat. A longer stalk with a couple leaves maybe. The marks of been hit here and there in the apple doesn''t help much. I get the feeling that a different crop (maybe landscape) would have worked better.</td>', 'Nice lighting, well executed. I would prefer a better defined shadow and a bit more texture in the apple it seems a bit flat. A longer stalk with a couple leaves maybe. The marks of been hit here and there in the apple doesn''t help much. I get the feeling that a different crop (maybe landscape) would have worked better.', '2012-11-05 12:46:06.000000', NULL, 1),
(6898822, 1039361, 96509, '<td valign="top">Nice texture and shadows.</td>', 'Nice texture and shadows.', '2012-11-05 12:47:50.000000', NULL, 1),
(6898823, 1039438, 96509, '<td valign="top">good work on transmitting the emotion.</td>', 'good work on transmitting the emotion.', '2012-11-05 12:48:52.000000', NULL, 1),
(6898825, 1039151, 96509, '<td valign="top">I like it, I cann''t stop thinking on stories that goes with the image, many possibilities.</td>', 'I like it, I cann''t stop thinking on stories that goes with the image, many possibilities.', '2012-11-05 12:51:44.000000', NULL, 1),
(6898826, 1039149, 96509, '<td valign="top">I like the perspective and texture of the floor. Not crazy about the color but I think it does sort of work with the image.</td>', 'I like the perspective and texture of the floor. Not crazy about the color but I think it does sort of work with the image.', '2012-11-05 12:52:59.000000', NULL, 1),
(6898827, 1039567, 96509, '<td valign="top">I really like the expression. Nice shot</td>', 'I really like the expression. Nice shot', '2012-11-05 12:53:45.000000', NULL, 1),
(6898829, 1039341, 96509, '<td valign="top">Wonderful detail.</td>', 'Wonderful detail.', '2012-11-05 12:54:01.000000', NULL, 1),
(6898830, 1039617, 96509, '<td valign="top">Love the abstract, the tip is a bit distracting although it also provides something extra to the image.</td>', 'Love the abstract, the tip is a bit distracting although it also provides something extra to the image.', '2012-11-05 12:54:44.000000', NULL, 1),
(6898834, 1039603, 96509, '<td valign="top">I like the nice shallow DOF in the right place. Also I think the shadows towards the foreground work very well with the reflections towards the background. Been picky the dark to bright transition in the teeths seems a bit too abrupt and distracting.</td>', 'I like the nice shallow DOF in the right place. Also I think the shadows towards the foreground work very well with the reflections towards the background. Been picky the dark to bright transition in the teeths seems a bit too abrupt and distracting.', '2012-11-05 13:00:01.000000', NULL, 1),
(6898840, 1039008, 96509, '<td valign="top">I think that the image would benefit of having a subject towards the end of the path. In my opinion the eyes follow the path but end up in a rather boring subject.</td>', 'I think that the image would benefit of having a subject towards the end of the path. In my opinion the eyes follow the path but end up in a rather boring subject.', '2012-11-05 13:19:39.000000', NULL, 1),
(6898844, 1039552, 96509, '<td valign="top">I think that a different DOF might have worked better. Maybe approaching with a smaller angle in order to have sharp focus on the marriage word and the rest quite out of focus.</td>', 'I think that a different DOF might have worked better. Maybe approaching with a smaller angle in order to have sharp focus on the marriage word and the rest quite out of focus.', '2012-11-05 13:23:03.000000', NULL, 1),
(6898847, 1039664, 96509, '<td valign="top">I am not fan of this type of processing, too artificial.</td>', 'I am not fan of this type of processing, too artificial.', '2012-11-05 13:27:02.000000', NULL, 1),
(6898850, 1039097, 96509, '<td valign="top">I found the overall bluish tint unpleasing. I like the texture of the elephants. Maybe a macro shot of one of the figures with a more sharper shadows would be interesting.</td>', 'I found the overall bluish tint unpleasing. I like the texture of the elephants. Maybe a macro shot of one of the figures with a more sharper shadows would be interesting.', '2012-11-05 13:30:48.000000', NULL, 1),
(6898870, 1039668, 112739, '<td valign="top">Has to be one of the most bizarre images I''ve ever seen.</td>', 'Has to be one of the most bizarre images I''ve ever seen.', '2012-11-05 13:50:10.000000', NULL, 1),
(6898878, 1039164, 112739, '<td valign="top">My usual understanding of a shadow would be to be able to see it being cast away from a light source. This interpretation of an implied shadow works for  me too. Very interesting image.</td>', 'My usual understanding of a shadow would be to be able to see it being cast away from a light source. This interpretation of an implied shadow works for  me too. Very interesting image.', '2012-11-05 13:55:40.000000', NULL, 1),
